     6→
     7→plugins {
     8→	id "java-library"
     9→	id "maven-publish"
    10→}
    11→
    12→group = "com.danawa.search"
    13→version = "1.0.0"
    14→
    15→ext {
    16→	esVersion = '9.1.2'
    17→	luceneVersion = '10.1.0'  // ES 9.1.2 호환 Lucene 버전
    18→}
