    22→		languageVersion = JavaLanguageVersion.of(21)
    23→	}
    24→}
    25→
    26→compileJava {
    27→	options.encoding = "UTF-8"
    28→	options.incremental = true
    29→	options.fork = true
    30→	options.failOnError = false
    31→}
    32→compileTestJava.options.encoding = "UTF-8"
    33→
    34→repositories {
    35→	mavenCentral()
    36→	mavenLocal()
    37→}
    38→
    39→sourceSets {
    40→	main {
