    92→task copyToDependencies(type: Copy) {
    93→	from (configurations.runtimeClasspath) {
    94→		include "json-*", "slf4j-api*", "snakeyaml-*", "commons-io-*"
    95→	}
    96→	from ("src/main/resources") {
    97→		include "*.properties"
