   111→	from (configurations.runtimeClasspath) {
   112→		include "*.jar"
   113→	}
   114→	from(jar.archiveFile) {
   115→		include "*.jar"
   116→	}
   117→	duplicatesStrategy = DuplicatesStrategy.EXCLUDE
