   125→/**
   126→ * gradle 커맨드에서 다음과 같이 테스트 실행 가능
   127→ * ./gradlew --no-daemon test --tests -DLOG_LEVEL=TRACE -DSYSPROP_LAUNCH_FOR_BUILD=false ProductNameAnalysisFilterTest.testFilter
   128→ **/
   129→test {
   130→	String launchForBuild = System.getProperty("SYSPROP_LAUNCH_FOR_BUILD")
   131→	String dictSetting = System.getProperty("SYSPROP_TEST_DICTIONARY_SETTING")
   132→	String logLevel = System.getProperty("LOG_LEVEL")
   133→	if ("false".equals(launchForBuild)) {
   134→		systemProperty "SYSPROP_LAUNCH_FOR_BUILD", "false"
   135→		testLogging.showStandardStreams = true
   136→	} else {
   137→		systemProperty "SYSPROP_LAUNCH_FOR_BUILD", "true"
   138→	}
   139→	if (dictSetting == null || "".equals(dictSetting)) {
   140→		systemProperty "SYSPROP_TEST_DICTIONARY_SETTING", "INTERNAL"
   141→	} else {
   142→		systemProperty "SYSPROP_TEST_DICTIONARY_SETTING", dictSetting
   143→	}
   144→	if (logLevel == null || "".equals(logLevel)) {
   145→		systemProperty "LOG_LEVEL", System.getProperty("DEBUG")
   146→	} else {
   147→		systemProperty "LOG_LEVEL", logLevel
   148→	}
   149→	systemProperty "SYSPROP_TEST_DICTIONARY_LOAD_EXTRA", System.getProperty("SYSPROP_TEST_DICTIONARY_LOAD_EXTRA")
   150→	systemProperty "SYSPROP_SAMPLE_TEXT_PATH", System.getProperty("SYSPROP_SAMPLE_TEXT_PATH")
   151→	systemProperty "log4j.configurationFile", System.getProperty("log4j.configurationFile")
   152→	systemProperty "file.encoding", "UTF-8"
   153→    dependsOn cleanTest
   154→}
   155→
   156→// ES 플러그인 배포용 ZIP 파일 생성
   157→task pluginZip(type: Zip) {
   158→	dependsOn(copyToDependencies, copyJars)
   159→
   160→	archiveBaseName = 'analysis-danuri'
   161→	archiveVersion = version
   162→	destinationDirectory = layout.buildDirectory.dir('distributions')
   163→
   164→	from(layout.buildDirectory.dir('libs')) {
   165→		include '**/*'
   166→	}
   167→}
   168→
   169→build.dependsOn(copyToDependencies, copyJars, pluginZip)

