     7→public class CharVector implements CharSequence, Comparable<CharSequence>, Serializable {
     8→	private static final long serialVersionUID = 1L;
     9→
    10→	private char[] array;
    11→	private int offset;
    12→	private int length;
    13→	protected int hash;
    14→
    15→	private boolean ignoreCase;
    16→
    17→	public CharVector() { }
    18→
    19→	public CharVector(CharSequence str) { this(str, false); }
    20→
    21→	public CharVector(CharSequence str, boolean ignoreCase) {
    22→		if (str != null) {
    23→			array = String.valueOf(str).toCharArray();
    24→			offset = 0;
    25→			length = array.length;
    26→		} else {
    27→			array = new char[0];
    28→			offset = 0;
    29→			length = 0;
    30→		}
    31→		this.ignoreCase = ignoreCase;
    32→	}
    33→
    34→	public CharVector(char[] array) {
    35→		this(array, 0, array.length);
    36→	}
    37→
    38→	public CharVector(char[] array, boolean ignoreCase) {
    39→		this(array, 0, array.length, ignoreCase);
    40→	}
    41→
    42→	public CharVector(char[] array, int offset, int length) {
    43→		this(array, offset, length, false);
    44→	}
    45→
    46→	public CharVector(char[] array, int offset, int length, boolean ignoreCase) {
    47→		this.array = array;
    48→		this.offset = offset;
    49→		this.length = length;
    50→		this.hash = 0;
    51→		this.ignoreCase = ignoreCase;
    52→	}
    53→
    54→	public void init(char[] array, int offset, int length) {
    55→		this.array = array;
    56→		this.offset = offset;
    57→		this.length = length;
    58→		this.hash = 0;
    59→	}
    60→
    61→	public void init(int offset, int length) {
    62→		this.offset = offset;
    63→		this.length = length;
    64→		this.hash = 0;
    65→	}
    66→
    67→	public void offset(int offset) {
    68→		this.offset = offset;
    69→		this.hash = 0;
    70→	}
    71→
    72→	public void length(int length) {
    73→		this.length = length;
    74→		this.hash = 0;
    75→	}
    76→
    77→	public void ignoreCase() {
    78→		if (!ignoreCase) {
    79→			this.ignoreCase = true;
    80→			hash = 0;
    81→		}
    82→	}
    83→
    84→	public void verifyCase() {
    85→		if (ignoreCase) {
    86→			this.ignoreCase = false;
    87→			hash = 0;
    88→		}
    89→	}
    90→
    91→	public boolean isIgnoreCase() {
    92→		return ignoreCase;
    93→	}
    94→
    95→	public int hashCode() {
    96→		// 해시코드는 대소문자 구분없이 모두 대문자 기준으로 만들어준다.
    97→		if (hash > 0) { return hash; }
    98→		int h = 0;
    99→		int off = offset;
   100→		for (int i = 0; i < length; i++) {
   101→			int ch = array[off++];
   102→			ch = toUpperChar(ch);
   103→			h = 31 * h + ch;
   104→		}
   105→		hash = h;
   106→		return h;
   107→	}
   108→
   109→	public CharVector trim() {
   110→		while (length > 0 && array[offset] == ' ') {
   111→			offset++;
   112→			length--;
   113→		}
   114→		while (length > 0 && array[offset + length - 1] == ' ') {
   115→			length--;
   116→		}
   117→		hash = 0;
   118→		return this;
   119→	}
   120→
   121→	@Override
   122→	public String toString() {
   123→		if (length > 0) {
   124→			return new String(array, offset, length);
   125→		} else {
   126→			return "";
   127→		}
   128→	}
   129→
   130→	@Override
   131→	public boolean equals(Object anObject) {
   132→		if (this == anObject) { return true; }
   133→		if (anObject instanceof CharVector) {
   134→			CharVector anotherArray = (CharVector) anObject;
   135→			int n = length;
   136→			if (n == anotherArray.length) {
   137→				if (ignoreCase || anotherArray.ignoreCase) {
   138→					// 둘중 하나라도 ignorecase이면 ignorecase로 비교한다.
   139→					for (int i = 0; i < length; i++) {
   140→						if (toUpperChar(charAt(i)) != toUpperChar(anotherArray.charAt(i))) {
   141→							return false;
   142→						}
   143→					}
   144→				} else {
   145→					for (int i = 0; i < length; i++) {
   146→						if (charAt(i) != anotherArray.charAt(i)) {
   147→							return false;
   148→						}
   149→					}
   150→				}
   151→				return true;
   152→			}
   153→		} else if (anObject instanceof CharSequence) {
   154→
   155→		}
   156→		return false;
   157→	}
   158→
   159→	@Override
   160→	public CharVector clone() {
   161→		// share array reference
   162→		CharVector cv = new CharVector(array, offset, length, ignoreCase);
   163→		cv.hash = hash;
   164→		return cv;
   165→	}
   166→
   167→	@Override
   168→	public int compareTo(CharSequence cs) {
   169→		int len1 = this.length;
   170→		int len2 = cs.length();
   171→		int minlen = len1;
   172→		if (minlen > len2) {
   173→			minlen = len2;
   174→		}
   175→		for (int cinx = 0; cinx < minlen; cinx++) {
   176→			char c1 = this.charAt(cinx);
   177→			char c2 = cs.charAt(cinx);
   178→			if (c1 == c2) {
   179→			} else if (c1 > c2) {
   180→				return 1;
   181→			} else if (c1 < c2) {
   182→				return -1;
   183→			}
   184→		}
   185→		if (len1 == len2) {
   186→			return 0;
   187→		} else if (len1 > len2) {
   188→			return 1;
   189→		} else if (len1 < len2) {
   190→			return -1;
   191→		}
   192→		return 0;
   193→	}
   194→
   195→	@Override
   196→	public char charAt(int inx) {
   197→		char ch = array[offset + inx];
   198→		if (ignoreCase) {
   199→			if ((ch <= 'z' && ch >= 'a')) {
   200→				// 소문자이면..
   201→				ch -= 32;
   202→			}
   203→		}
   204→		return ch;
   205→	}
   206→
   207→	private char toUpperChar(int ch) {
   208→		if ((ch <= 'z' && ch >= 'a')) {
   209→			// 소문자이면..
   210→			ch -= 32;
   211→		}
   212→		return (char) ch;
   213→	}
   214→
   215→	// 내부 공백을 삭제해준다.
   216→	public CharVector removeWhitespaces() {
   217→		int len = 0;
   218→		for (int i = 0; i < length; i++) {
   219→			if (array[offset + i] != ' ') {
   220→				array[offset + len++] = array[offset + i];
   221→			}
   222→		}
   223→		length = len;
   224→		hash = 0;
   225→		return this;
   226→	}
   227→
   228→	public boolean hasWhitespaces() {
   229→		for (int i = 0; i < length; i++) {
   230→			if (array[offset + i] == ' ') {
   231→				return true;
   232→			}
   233→		}
   234→		return false;
   235→	}
   236→
   237→	public char[] array() {
   238→		return array;
   239→	}
   240→
   241→	public int offset() {
   242→		return offset;
   243→	}
   244→
   245→	@Override
   246→	public int length() {
   247→		return length;
   248→	}
   249→
   250→	@Override
   251→	public CharSequence subSequence(int startIndex, int endIndex) {
   252→		CharVector cv = new CharVector();
   253→		cv.array = this.array;
   254→		cv.offset = this.offset + startIndex;
   255→		cv.length = endIndex - startIndex + 1;
   256→		return cv;
   257→	}
   258→
   259→	public List<CharVector> splitByWhitespace() {
   260→		return splitByWhitespace(this);
   261→	}
   262→
   263→	public static CharVector valueOf(Object o) {
   264→		CharVector ret;
   265→		if (o == null) {
   266→			ret = null;
   267→		} else if (o instanceof CharVector) {
   268→			ret = (CharVector) o;
   269→		} else {
   270→			ret = new CharVector(String.valueOf(o));
   271→		}
   272→		return ret;
   273→	}
   274→
   275→	public static List<CharVector> splitByWhitespace(CharVector term) {
   276→		int start = 0;
   277→		boolean isPrevWhitespace = true;
   278→		List<CharVector> list = new ArrayList<>();
   279→		for (int i = 0; i < term.length(); i++) {
   280→			char ch = term.charAt(i);
   281→			if (ch == ' ') {
   282→				if (!isPrevWhitespace) {
   283→					list.add(new CharVector(term.array(), start + term.offset(), i - start, term.isIgnoreCase()));
   284→				}
   285→				start = i + 1;
   286→				isPrevWhitespace = true;
   287→			} else {
   288→				isPrevWhitespace = false;
   289→			}
   290→		}
   291→		if (!isPrevWhitespace) {
   292→			list.add(new CharVector(term.array(), start + term.offset(), term.length() - start, term.isIgnoreCase()));
   293→		}
   294→		return list;
   295→	}
   296→}
