     4→import org.apache.logging.log4j.LogManager;
     5→import org.apache.logging.log4j.Logger;
     6→
     7→import java.util.ArrayList;
     8→import java.util.List;
     9→
    10→public class RuleEntry implements Comparable<RuleEntry> {
    11→
    12→    private static final Logger logger = LogManager.getLogger(RuleEntry.class);
    13→
    14→    public char[] buf;
    15→    public int start;
    16→    public int length;
    17→    public int startOffset;
    18→    public int endOffset;
    19→    public String type;
    20→    public boolean modifiable;
    21→    public CharSequence[] synonym;
    22→    public List<RuleEntry> subEntry;
    23→
    24→    public RuleEntry(char[] buf, int start, int length, int startOffset, int endOffset, String type) {
    25→        this.buf = buf;
    26→        this.start = start;
    27→        this.length = length;
    28→        this.startOffset = startOffset;
    29→        this.endOffset = endOffset;
    30→        this.type = type;
    31→        this.subEntry = new ArrayList<>();
    32→        this.modifiable = true;
    33→    }
    34→
    35→    public CharVector makeTerm(CharVector cv) {
    36→        return makeTerm(cv, start, length);
    37→    }
    38→
    39→    public CharVector makeTerm(CharVector cv, int start, int length) {
    40→        if (cv == null) {
    41→            cv = new CharVector();
    42→        }
    43→        cv.init(buf, start, length);
    44→        return cv;
    45→    }
    46→
    47→    public RuleEntry clone() {
    48→        RuleEntry entry = new RuleEntry(buf, start, length, startOffset, endOffset, type);
    49→        entry.synonym = synonym;
    50→        entry.subEntry = subEntry;
    51→        return entry;
    52→    }
    53→
    54→    @Override public String toString() {
    55→        String str = "";
    56→        if (buf != null) {
    57→            try {
    58→                str = "\"" + new String(buf, start, length) + "\"";
    59→            } catch (Exception ex) {
    60→                str = "\"" + new String(buf) + "\" [" + start + ":" + length + "]";
    61→                logger.debug("EE:{}", ex.getMessage());
    62→            }
    63→        }
    64→        str += " / " + type + " / " + modifiable + " (" + start + "~" + (start + length) + "/" + startOffset + "~" + endOffset + ")";
    65→        if (subEntry != null) {
    66→            str += "[" + subEntry.size() + "]";
    67→        }
    68→        if (synonym != null) {
    69→            str += "[" + synonym.length + "]";
    70→        }
    71→        return str;
    72→    }
    73→
    74→    @Override public int compareTo(RuleEntry entry) {
    75→        int ret = 0;
    76→        ret = this.startOffset - entry.startOffset;
    77→        if (ret == 0) {
    78→            if (this.startOffset == this.endOffset) {
    79→                ret = -1;
    80→            } else if (entry.startOffset == entry.endOffset) {
    81→                ret = 1;
    82→            } else {
    83→                ret = entry.endOffset - this.endOffset;
    84→            }
    85→        }
    86→        return ret;
    87→    }
    88→}
    89→

