    96→    public static int split(RuleEntry entry, List<RuleEntry> queue, int baseInx) {
    97→        // if (entry.length < 2) { return 0; }
    98→        logger.trace("split entry ({}) : {}~{}", entry, entry.start, entry.length);
    99→        String ptype = null;
   100→        String ctype = null;
   101→        int st = 0;
   102→        int addInx = 0;
   103→        int offsetStarts = entry.startOffset;
   104→        for (int inx = 0; inx < entry.length; inx++) {
   105→            char ch = entry.buf[entry.start + inx];
   106→            ctype = getType(ch);
   107→            if (ptype != null && ptype != ctype) {
   108→                RuleEntry entryClone = entry.clone();
   109→                entryClone.start = entry.start + st;
   110→                entryClone.length = inx - st;
   111→                entryClone.type = ptype;
   112→
   113→                entryClone.startOffset = offsetStarts + st;
   114→                entryClone.endOffset = offsetStarts + st + entryClone.length;
   115→                entryClone.modifiable = true;
   116→                logger.trace("add splited entry : ({}) : {}~{}", entryClone, entryClone.start, entryClone.length);
   117→                if (entryClone.type != WHITESPACE) {
   118→                    queue.add(baseInx + addInx, entryClone);
   119→                    addInx++;
   120→                }
   121→                // 엔트리 클로닝시 서브엔트리가 복제되는 버그 수정
   122→                if (inx > 0) {
   123→                    entryClone.subEntry = new ArrayList<>();
   124→                    entryClone.synonym = null;
   125→                }
   126→                st = inx;
   127→            }
   128→            ptype = ctype;
   129→        }
   130→        if (addInx >= 0 && st < entry.length) {
   131→            RuleEntry entryClone = entry.clone();
   132→            if (ptype == null) {
   133→                ptype = ctype;
   134→            }
   135→            entryClone.start = entry.start + st;
   136→            entryClone.length = entry.length - st;
   137→            entryClone.startOffset = offsetStarts + st;
   138→            entryClone.endOffset = offsetStarts + st + entryClone.length;
   139→            entryClone.type = ptype;
   140→            entryClone.subEntry = new ArrayList<>();
   141→            entryClone.synonym = null;
   142→            logger.trace("add splited entry : ({}) : {}~{}", entryClone, entryClone.start, entryClone.length);
   143→            queue.add(baseInx + addInx, entryClone);
   144→            addInx++;
   145→        }
   146→        return addInx;
   147→    }
