   815→        while (iter.hasNext()) {
   816→            if (currentEntry == null) {
   817→                currentEntry = iter.next();
   818→            }
   819→
   820→            RuleEntry nextNextEntry;
   821→
   822→            if (currentEntry.length == 1 && ((currentEntry.type == ALPHA || (currentEntry.type == UNIT && Character.isAlphabetic(currentEntry.buf[currentEntry.start]))) || currentEntry.type == NUMBER)) {
   823→                // 다음 엔트리를 불러온다
   824→                if (iter.hasNext() && nextEntry == null) {
   825→                    nextEntry = iter.next();
   826→
   827→                    // 현재와 다음 엔트리를 비교 및 결합한다
   828→                    if (isConnected(currentEntry, nextEntry)) {
   829→                        combineNextEntry(tmpList, currentEntry, nextEntry, ALPHANUM);
   830→                    }
   831→                }
   832→
   833→                // 현재와 다음, 다다음 엔트리를 비교 및 결합한다
   834→                if (nextEntry != null && nextEntry.length == 1 && ((nextEntry.type == ALPHA || (nextEntry.type == UNIT && Character.isAlphabetic(nextEntry.buf[nextEntry.start]))) || nextEntry.type == NUMBER)) {
   835→                    if ((currentEntry.type == NUMBER && (nextEntry.type == ALPHA || (nextEntry.type == UNIT && Character.isAlphabetic(nextEntry.buf[nextEntry.start]))) || ((currentEntry.type == ALPHA || (currentEntry.type == UNIT && Character.isAlphabetic(currentEntry.buf[currentEntry.start]))) && nextEntry.type == NUMBER))) {
   836→                        // 다다음 엔트리를 불러온다
   837→                        if (iter.hasNext()) {
   838→                            nextNextEntry = iter.next();
   839→
   840→                            // 다다음 엔트리까지 확인해서 결합한다
   841→                            if (isConnected(currentEntry, nextEntry) && isConnected(nextEntry, nextNextEntry)) {
   842→                                if (nextNextEntry != null && nextEntry.length == 1 && nextNextEntry.length == 1 && ((nextEntry.type == ALPHA || nextEntry.type == UNIT && Character.isAlphabetic(nextEntry.buf[nextEntry.start])) && nextNextEntry.type == NUMBER || nextEntry.type == NUMBER && (nextNextEntry.type == ALPHA || nextNextEntry.type == UNIT && Character.isAlphabetic(nextNextEntry.buf[nextNextEntry.start])))) {
   843→                                    combineNextNextEntry(tmpList, currentEntry, nextEntry, nextNextEntry, ALPHANUM);
   844→                                }
   845→                            } else if (isConnected(nextEntry, nextNextEntry)) {
   846→                                if (nextNextEntry != null && nextEntry.length == 1 && nextNextEntry.length == 1 && ((nextEntry.type == ALPHA || nextEntry.type == UNIT && Character.isAlphabetic(nextEntry.buf[nextEntry.start])) && nextNextEntry.type == NUMBER || nextEntry.type == NUMBER && (nextNextEntry.type == ALPHA || nextNextEntry.type == UNIT && Character.isAlphabetic(nextNextEntry.buf[nextNextEntry.start])))) {
   847→                                    combineNextNextEntry(tmpList, nextEntry, nextNextEntry, ALPHANUM);
   848→                                }
   849→                            }
