    24→	private final static String DELIMITER = "\\s";
    25→	private static final Pattern ptn = Pattern.compile("^[\\x00-\\x7F]*$");
    26→	private Set<CharSequence> wordSet;
    27→
    28→	public SpaceDictionary() {
    29→		this(false);
    30→	}
    31→
    32→	public SpaceDictionary(boolean ignoreCase) {
    33→		super(ignoreCase);
