    51→	public void setWordSet(Set<CharSequence> wordSet) {
    52→		this.wordSet = wordSet;
    53→	}
    54→
    55→	public Set<CharSequence> getUnmodifiableWordSet() {
    56→		return Collections.unmodifiableSet(wordSet);
    57→	}
    58→
    59→	@Override
    60→	public void addEntry(CharSequence word, Object[] values, List<Object> columnList) {
    61→		if (values == null || values.length == 0) { return; }
    62→		String keyword = String.valueOf(values[0]).replaceAll(DELIMITER, "");
    63→		wordSet.add(new CharVector(String.valueOf(keyword), ignoreCase));
    64→		String[] list = String.valueOf(values[0]).split(DELIMITER);
    65→		super.addEntry(keyword, list, columnList);
    66→		for (int i = 0; i < list.length; i++) {
    67→			String str = list[i].trim();
    68→			// ASCII 골라내기
    69→			if (!ptn.matcher(str).find()) {
    70→				wordSet.add(new CharVector(String.valueOf(list[i]).trim(), ignoreCase));
    71→			}
    72→		}
    73→	}
    74→
    75→	@Override
    76→	@SuppressWarnings("resource")
    77→	public void writeTo(OutputStream out) throws IOException {
    78→		if (!(out instanceof BufferedOutputStream)) {
    79→			try { out = new BufferedOutputStream(out); } catch (Exception ignore) { }
    80→		}
    81→		super.writeTo(out);
    82→		DataOutput output = new OutputStreamDataOutput(out);
    83→		// write size of synonyms
    84→		output.writeVInt(wordSet.size());
    85→
    86→		// write synonyms
    87→		Iterator<CharSequence> synonymIter = wordSet.iterator();
    88→		for (; synonymIter.hasNext();) {
    89→			CharVector value = CharVector.valueOf(synonymIter.next());
    90→			output.writeUString(value.array(), value.offset(), value.length());
    91→		}
    92→		try { out.flush(); } catch (Exception ignore) { }
    93→	}
    94→
    95→	@Override
    96→	@SuppressWarnings("resource")
    97→	public void readFrom(InputStream in) throws IOException {
    98→		if (!(in instanceof BufferedInputStream)) {
    99→			try { in = new BufferedInputStream(in); } catch (Exception ignore) { }
   100→		}
   101→		super.readFrom(in);
   102→		DataInput input = new InputStreamDataInput(in);
   103→		wordSet = new HashSet<>();
   104→		int size = input.readVInt();
   105→		for (int entryInx = 0; entryInx < size; entryInx++) {
   106→			wordSet.add(new CharVector(input.readUString(), ignoreCase));
   107→		}
   108→	}
