   110→	@Override
   111→	public void reload(Object object) throws IllegalArgumentException {
   112→		if (object != null && object instanceof SpaceDictionary) {
   113→			super.reload(object);
   114→			SpaceDictionary spaceDictionary = (SpaceDictionary) object;
   115→			this.wordSet = spaceDictionary.getWordSet();
   116→		} else {
   117→			throw new IllegalArgumentException("Reload dictionary argument error. argument = " + object);
   118→		}
   119→	}
   120→}

