   162→	/**
   163→	 * Reads a long stored in variable-length format. Reads between one and nine bytes. Smaller values take fewer bytes. Negative
   164→	 * numbers are not supported.
   165→	 * <p>
   166→	 * The format is described further in {@link IndexOutput#writeVInt(int)}.
   167→	 * 
   168→	 * @see IndexOutput#writeVLong(long)
   169→	 */
   170→	public long readVLong() throws IOException {
   171→		/*
   172→		 * This is the original code of this method, but a Hotspot bug (see LUCENE-2975) corrupts the for-loop if readByte() is
   173→		 * inlined. So the loop was unwinded! byte b = readByte(); long i = b & 0x7F; for (int shift = 7; (b & 0x80) != 0; shift
   174→		 * += 7) { b = readByte(); i |= (b & 0x7FL) << shift; } return i;
   175→		 */
   176→		byte b = readByte();
   177→		if (b >= 0) { return b; }
   178→		long i = b & 0x7FL;
   179→		b = readByte();
   180→		i |= (b & 0x7FL) << 7;
   181→		if (b >= 0) { return i; }
   182→		b = readByte();
   183→		i |= (b & 0x7FL) << 14;
   184→		if (b >= 0) { return i; }
   185→		b = readByte();
   186→		i |= (b & 0x7FL) << 21;
   187→		if (b >= 0) { return i; }
   188→		b = readByte();
   189→		i |= (b & 0x7FL) << 28;
   190→		if (b >= 0) { return i; }
   191→		b = readByte();
   192→		i |= (b & 0x7FL) << 35;
   193→		if (b >= 0) { return i; }
   194→		b = readByte();
   195→		i |= (b & 0x7FL) << 42;
   196→		if (b >= 0) { return i; }
   197→		b = readByte();
   198→		i |= (b & 0x7FL) << 49;
   199→		if (b >= 0) { return i; }
   200→		b = readByte();
   201→		i |= (b & 0x7FL) << 56;
   202→		if (b >= 0) { return i; }
   203→		throw new IOException("Invalid vLong detected (negative values disallowed)");
   204→	}
