   221→	public String readUTF8String() throws IOException {
   222→		int charCount = readVInt();
   223→		char[] chars = CachedCharArray.getCharArray(charCount);
   224→		int c, charIndex = 0;
   225→		while (charIndex < charCount) {
   226→			c = readByte() & 0xff;
   227→			switch (c >> 4) {
   228→			case 0:
   229→			case 1:
   230→			case 2:
   231→			case 3:
   232→			case 4:
   233→			case 5:
   234→			case 6:
   235→			case 7:
   236→				chars[charIndex++] = (char) c;
   237→				break;
   238→			case 12:
   239→			case 13:
   240→				chars[charIndex++] = (char) ((c & 0x1F) << 6 | readByte() & 0x3F);
   241→				break;
   242→			case 14:
   243→				chars[charIndex++] = (char) ((c & 0x0F) << 12 | (readByte() & 0x3F) << 6 | (readByte() & 0x3F) << 0);
   244→				break;
   245→			}
   246→		}
   247→		return new String(chars, 0, charCount);
   248→	}
