   305→	public Object readGenericValue() throws IOException {
   306→		byte type = readByte();
   307→		switch (type) {
   308→		case -1:
   309→			return null;
   310→		case 0:
   311→			return readString();
   312→		case 1:
   313→			return readInt();
   314→		case 2:
   315→			return readLong();
   316→		case 3:
   317→			return readFloat();
   318→		case 4:
   319→			return readDouble();
   320→		case 5:
   321→			return readBoolean();
   322→		case 6:
   323→			int bytesSize = readVInt();
   324→			byte[] value = new byte[bytesSize];
   325→			readBytes(value, 0, bytesSize);
   326→			return value;
   327→		case 7:
   328→			int size = readVInt();
   329→			List<Object> list = new ArrayList<>(size);
   330→			for (int i = 0; i < size; i++) {
   331→				list.add(readGenericValue());
   332→			}
   333→			return list;
   334→		case 8:
   335→			int size8 = readVInt();
   336→			Object[] list8 = new Object[size8];
   337→			for (int i = 0; i < size8; i++) {
   338→				list8[i] = readGenericValue();
   339→			}
   340→			return list8;
   341→		case 9:
   342→			int size9 = readVInt();
   343→			Map<String, Object> map9 = new LinkedHashMap<>(size9);
   344→			for (int i = 0; i < size9; i++) {
   345→				map9.put(readString(), readGenericValue());
   346→			}
   347→			return map9;
   348→		case 10:
   349→			int size10 = readVInt();
   350→			Map<String, Object> map10 = new HashMap<>(size10);
   351→			for (int i = 0; i < size10; i++) {
   352→				map10.put(readString(), readGenericValue());
   353→			}
   354→			return map10;
   355→		case 11:
   356→			return readByte();
   357→		case 12:
   358→			return new Date(readLong());
   359→		case 14:
   360→			int size14 = readVInt();
   361→			BytesBuffer b = new BytesBuffer(size14);
   362→			readBytes(b);
   363→			return b;
   364→		case 16:
   365→			return readShort();
   366→		default:
   367→			throw new IOException("Can't read unknown type [" + type + "]");
   368→		}
   369→	}
