   172→	/** Copy numBytes bytes from input to ourself. */
   173→	public void copyBytes(DataInput input, long numBytes) throws IOException {
   174→		assert numBytes >= 0 : "numBytes=" + numBytes;
   175→		long left = numBytes;
   176→		if (copyBuffer == null) {
   177→			copyBuffer = new byte[COPY_BUFFER_SIZE];
   178→		}
   179→		while (left > 0) {
   180→			final int toCopy;
   181→			if (left > COPY_BUFFER_SIZE) {
   182→				toCopy = COPY_BUFFER_SIZE;
   183→			} else {
   184→				toCopy = (int) left;
   185→			}
   186→			input.readBytes(copyBuffer, 0, toCopy);
   187→			writeBytes(copyBuffer, 0, toCopy);
   188→			left -= toCopy;
   189→		}
   190→	}
