   322→		if (v.length > 0) {
   323→			if (start >= v.length) {
   324→				throw new IOException("start position exceeds array length. start=" + start + ", array.length=" + v.length);
   325→			}
   326→			if (start + length > v.length) {
   327→				newLength = v.length - start;
   328→			}
   329→			for (int i = 0; i < newLength; i++) {
   330→				writeAChar(v[start + i], upperCase);
   331→			}
   332→		} else {
   333→			// 기록된바 없음.
   334→			newLength = 0;
   335→		}
   336→		// 나머지 0으로 기록. length와 newLength 가 동일하다면 수행되지 않음.
   337→		for (int i = 0; i < length - newLength; i++) {
   338→			writeAChar(0);
   339→		}
   340→	}
   341→
   342→	public void writeUChars(char[] v, int start, int length) throws IOException {
   343→		writeUChars(v, start, length, false);
   344→	}
   345→
   346→	public void writeUChars(char[] v, int start, int length, boolean upperCase) throws IOException {
   347→		if (length == 0) { return; }
   348→		int newLength = length;
   349→		if (v.length > 0) {
   350→			if (start >= v.length) {
   351→				throw new IOException("start position exceeds array length. start=" + start + ", array.length=" + v.length);
   352→			}
   353→			if (start + length > v.length) {
   354→				newLength = v.length - start;
   355→			}
   356→			for (int i = 0; i < newLength; i++) {
   357→				writeUChar(v[start + i], upperCase);
   358→			}
   359→		} else {
   360→			// 기록된바 없음.
   361→			newLength = 0;
   362→		}
   363→		// 나머지 0으로 기록. length와 newLength 가 동일하다면 수행되지 않음.
   364→		for (int i = 0; i < length - newLength; i++) {
   365→			writeUChar(0);
   366→		}
   367→	}
