   369→	public void writeStringArray(String[] array) throws IOException {
   370→		writeVInt(array.length);
   371→		for (String s : array) {
   372→			writeString(s);
   373→		}
   374→	}
   375→
   376→	/**
   377→	 * Writes a string array, for nullable string, writes it as 0 (empty string).
   378→	 */
   379→	public void writeStringArrayNullable(String[] array) throws IOException {
   380→		if (array == null) {
   381→			writeVInt(0);
   382→		} else {
   383→			writeVInt(array.length);
   384→			for (String s : array) {
   385→				writeString(s);
   386→			}
   387→		}
   388→	}
   389→
   390→	public void writeMap(Map<String, Object> map) throws IOException {
   391→		writeGenericValue(map);
   392→	}
   393→
   394→	public void writeGenericValue(Object value) throws IOException {
   395→		if (value == null) {
   396→			writeByte((byte) -1);
   397→			return;
   398→		}
   399→		Class<?> type = value.getClass();
   400→		if (type == String.class) {
   401→			writeByte((byte) 0);
   402→			writeString((String) value);
   403→		} else if (type == Integer.class) {
   404→			writeByte((byte) 1);
   405→			writeInt((Integer) value);
   406→		} else if (type == Long.class) {
   407→			writeByte((byte) 2);
   408→			writeLong((Long) value);
   409→		} else if (type == Float.class) {
   410→			writeByte((byte) 3);
   411→			writeFloat((Float) value);
   412→		} else if (type == Double.class) {
   413→			writeByte((byte) 4);
   414→			writeDouble((Double) value);
   415→		} else if (type == Boolean.class) {
   416→			writeByte((byte) 5);
   417→			writeBoolean((Boolean) value);
   418→		} else if (type == byte[].class) {
   419→			writeByte((byte) 6);
   420→			writeVInt(((byte[]) value).length);
   421→			writeBytes(((byte[]) value));
   422→		} else if (value instanceof List) {
   423→			writeByte((byte) 7);
   424→			List<?> list = (List<?>) value;
   425→			writeVInt(list.size());
   426→			for (Object o : list) {
   427→				writeGenericValue(o);
   428→			}
   429→		} else if (value instanceof Object[]) {
   430→			writeByte((byte) 8);
   431→			Object[] list = (Object[]) value;
   432→			writeVInt(list.length);
   433→			for (Object o : list) {
   434→				writeGenericValue(o);
   435→			}
   436→		} else if (value instanceof Map) {
   437→			if (value instanceof LinkedHashMap) {
   438→				writeByte((byte) 9);
   439→			} else {
   440→				writeByte((byte) 10);
   441→			}
   442→			@SuppressWarnings("unchecked")
   443→			Map<String, Object> map = (Map<String, Object>) value;
   444→			writeVInt(map.size());
   445→			for (Map.Entry<String, Object> entry : map.entrySet()) {
   446→				writeString(entry.getKey());
   447→				writeGenericValue(entry.getValue());
   448→			}
   449→		} else if (type == Byte.class) {
   450→			writeByte((byte) 11);
   451→			writeByte((Byte) value);
   452→		} else if (type == Date.class) {
   453→			writeByte((byte) 12);
   454→			writeLong(((Date) value).getTime());
   455→		} else if (value instanceof BytesBuffer) {
   456→			writeByte((byte) 14);
   457→			writeVInt(((BytesBuffer) value).length());
   458→			writeBytes((BytesBuffer) value);
   459→		} else if (type == Short.class) {
   460→			writeByte((byte) 16);
   461→			writeShort((Short) value);
   462→		} else {
   463→			throw new IOException("Can't write type [" + type + "]");
   464→		}
   465→	}
   466→}

