     3→import java.util.Map;
     4→import java.util.concurrent.ConcurrentHashMap;
     5→/**
     6→ * 2021.7.15 swsong
     7→ * HashMap + Synchronized 조합을 ConcurrentHashMap 으로 변경함.
     8→ *
     9→ * */
    10→@SuppressWarnings("unchecked")
    11→public final class ContextStore {
    12→    private final static Map<Class<?>, ContextStore> STORE = new ConcurrentHashMap<>();
    13→    private Map<String, Object> map;
    14→
    15→    public final static ContextStore getStore(Class<?> cls) {
    16→        if (cls != null) {
    17→            if (STORE.containsKey(cls)) {
    18→                return STORE.get(cls);
    19→            } else {
    20→                ContextStore store = new ContextStore();
    21→                STORE.put(cls, store);
    22→                return store;
    23→            }
    24→        }
    25→        return null;
    26→    }
    27→
    28→    private ContextStore() {
    29→        map = new ConcurrentHashMap<>();
    30→    }
    31→
    32→    public boolean containsKey(String key) {
    33→        return map.containsKey(key);
    34→    }
    35→
    36→    public void put(String key, Object obj) {
    37→        map.put(key, obj);
    38→    }
    39→
    40→    public Double getDouble(String key, Double def) {
    41→        Double ret = null;
    42→        Object obj = map.get(key);
    43→        if (obj != null) {
    44→            if (obj instanceof String) {
    45→                ret = Double.parseDouble((String) obj);
    46→            } else {
    47→                ret = def;
    48→            }
    49→        }
    50→        return ret;
    51→    }
    52→
    53→    public Float getFloat(String key, Float def) {
    54→        Float ret = null;
    55→        Object obj = map.get(key);
    56→        if (obj != null) {
    57→            if (obj instanceof String) {
    58→                ret = Float.parseFloat((String) obj);
    59→            } else {
    60→                ret = def;
    61→            }
    62→        }
    63→        return ret;
    64→    }
    65→
    66→    public Long getLong(String key, Long def) {
    67→        Long ret = null;
    68→        Object obj = map.get(key);
    69→        if (obj != null) {
    70→            if (obj instanceof String) {
    71→                ret = Long.parseLong((String) obj);
    72→            } else {
    73→                ret = def;
    74→            }
    75→        }
    76→        return ret;
    77→    }
    78→
    79→    public Integer getInteger(String key, Integer def) {
    80→        Integer ret = null;
    81→        Object obj = map.get(key);
    82→        if (obj != null) {
    83→            if (obj instanceof String) {
    84→                ret = Integer.parseInt((String) obj);
    85→            } else {
    86→                ret = def;
    87→            }
    88→        }
    89→        return ret;
    90→    }
    91→
    92→    public String getString(String key, String def) {
    93→        String ret = null;
    94→        Object obj = map.get(key);
    95→        if (obj != null) {
    96→            ret = String.valueOf(obj);
    97→        } else {
    98→            ret = def;
    99→        }
   100→        return ret;
   101→    }
   102→
   103→    public <T> T getAs(String key, Class<T> cls) {
   104→        T ret = null;
   105→        Object obj = map.get(key);
   106→        if (obj != null) {
   107→            ret = (T) obj;
   108→        }
   109→        return ret;
   110→    }
   111→}

