   153→	@Override
   154→	public void addSourceLineEntry(CharSequence line) {
   155→		if (line == null) { return; }
   156→		String[] kv = String.valueOf(line).split("\t");
   157→		if (kv.length == 1) {
   158→			String value = kv[0].trim();
   159→			addEntry(null, new String[] { value }, null);
   160→		} else if (kv.length == 2) {
   161→			String keyword = kv[0].trim();
   162→			String value = kv[1].trim();
   163→			addEntry(keyword, new String[] { value }, null);
   164→		}
   165→	}
