    64→    @Inject
    65→    public TransportReloadDictAction(
    66→            ThreadPool threadPool,
    67→            ClusterService clusterService,
    68→            TransportService transportService,
    69→            ActionFilters actionFilters) {
    70→        super(
    71→            ACTION_NAME,
    72→            clusterService,
    73→            transportService,
    74→            actionFilters,
    75→            // ES 9.1.2: Writeable.Reader만 전달 (노드 요청 역직렬화용)
    76→            ReloadDictNodeRequest::new,
    77→            // ES 9.1.2: MANAGEMENT executor (사전 로딩은 I/O 바운드 작업)
    78→            threadPool.executor(ThreadPool.Names.MANAGEMENT)
    79→        );
    80→    }
    81→
    82→    /**
    83→     * 클러스터 전체 응답 생성
    84→     */
    85→    @Override
    86→    protected ReloadDictNodesResponse newResponse(
    87→            ReloadDictNodesRequest request,
    88→            List<ReloadDictNodeResponse> responses,
    89→            List<FailedNodeException> failures) {
    90→        return new ReloadDictNodesResponse(clusterService.getClusterName(), responses, failures);
    91→    }
    92→
    93→    /**
    94→     * 개별 노드 요청 생성 - 최소한의 페이로드만 전달
    95→     */
    96→    @Override
    97→    protected ReloadDictNodeRequest newNodeRequest(ReloadDictNodesRequest request) {
    98→        return new ReloadDictNodeRequest(request.getDictionaryType());
    99→    }
   100→
   101→    /**
   102→     * 노드 응답 역직렬화
   103→     */
   104→    @Override
   105→    protected ReloadDictNodeResponse newNodeResponse(StreamInput in, DiscoveryNode node) throws IOException {
   106→        return new ReloadDictNodeResponse(in);
   107→    }
   108→
   109→    /**
   110→     * 각 노드에서 실행되는 핵심 로직
   111→     */
   112→    @Override
   113→    protected ReloadDictNodeResponse nodeOperation(ReloadDictNodeRequest request, Task task) {
   114→        DiscoveryNode localNode = clusterService.localNode();
   115→        long startTime = System.currentTimeMillis();
   116→
   117→        try {
   118→            logger.info("[{}] Dictionary reload started, type={}",
   119→                localNode.getName(), request.getDictionaryType());
   120→
   121→            // 사전 인스턴스 확인
   122→            if (!contextStore.containsKey(ProductNameDictionary.PRODUCT_NAME_DICTIONARY)) {
   123→                logger.warn("[{}] Dictionary not initialized", localNode.getName());
   124→                return new ReloadDictNodeResponse(
   125→                    localNode, false, "Dictionary not initialized", 0, 0
   126→                );
   127→            }
   128→
   129→            ProductNameDictionary dictionary = contextStore.getAs(
   130→                ProductNameDictionary.PRODUCT_NAME_DICTIONARY,
   131→                ProductNameDictionary.class
   132→            );
   133→
   134→            if (dictionary == null) {
   135→                return new ReloadDictNodeResponse(
   136→                    localNode, false, "Dictionary instance is null", 0, 0
   137→                );
   138→            }
   139→
   140→            // 사전 리로드 실행
   141→            ProductNameDictionary.reloadDictionary();
   142→
   143→            long elapsed = System.currentTimeMillis() - startTime;
   144→            int size = getDictionarySize(dictionary);
   145→
   146→            logger.info("[{}] Dictionary reload completed in {}ms, size={}",
   147→                localNode.getName(), elapsed, size);
   148→
   149→            return new ReloadDictNodeResponse(
   150→                localNode, true, "Reload successful", elapsed, size
   151→            );
   152→
   153→        } catch (Exception e) {
   154→            long elapsed = System.currentTimeMillis() - startTime;
   155→            logger.error("[{}] Dictionary reload failed: {}", localNode.getName(), e.getMessage(), e);
   156→
   157→            return new ReloadDictNodeResponse(
   158→                localNode, false, e.getMessage(), elapsed, 0
   159→            );
   160→        }
   161→    }
   162→
   163→    /**
   164→     * 사전 크기 조회 (안전하게 처리)
   165→     */
   166→    private int getDictionarySize(ProductNameDictionary dictionary) {
   167→        try {
   168→            if (dictionary.getDictionaryMap() != null) {
   169→                return dictionary.getDictionaryMap().size();
   170→            }
   171→        } catch (Exception e) {
   172→            logger.debug("Failed to get dictionary size", e);
   173→        }
   174→        return 0;
   175→    }
   176→}
