    17→ * + 영문은 모델명 규칙에 더 가까우며, (구현됨) 변형숫자 + 단위명 은 단위명 규칙에 더 가깝다. (폐기) 중간에 숫자만 똑 떼어가는
    18→ * 경우도 있으므로 앞, 뒤 속성 등을 유지하기 위해 큐가 필요하다. (구현됨) 유사어 속성도 같이 변경 되어야 한다.
    19→ *
    20→ * @author lupfeliz
    21→ */
    22→public class ProductNameParsingRule {
    23→
    24→    private static final Logger logger = LogManager.getLogger(ProductNameParsingRule.class);
    25→
    26→    private KoreanWordExtractor extractor;
    27→    protected AnalyzerOption option;
    28→    private SetDictionary unitDictionary;
    29→    private SpaceDictionary spaceDictionary;
    30→    private SynonymDictionary unitSynonymDictionary;
    31→    private SynonymDictionary synonymDictionary;
    32→    private SetDictionary userDictionary;
    33→    private CompoundDictionary compoundDictionary;
    34→    private SetDictionary stopDictionary;
    35→
    36→    private ProductNameParsingRule() {
    37→    }
    38→
    39→    public ProductNameParsingRule(KoreanWordExtractor extractor, ProductNameDictionary dictionary,
    40→                                  AnalyzerOption option) {
    41→        this.extractor = extractor;
    42→        this.option = option;
    43→        if (dictionary != null) {
    44→            unitDictionary = dictionary.getDictionary(ProductNameDictionary.DICT_UNIT, SetDictionary.class);
    45→            synonymDictionary = dictionary.getDictionary(ProductNameDictionary.DICT_SYNONYM, SynonymDictionary.class);
    46→            unitSynonymDictionary = dictionary.getDictionary(ProductNameDictionary.DICT_UNIT_SYNONYM, SynonymDictionary.class);
    47→            spaceDictionary = dictionary.getDictionary(ProductNameDictionary.DICT_SPACE, SpaceDictionary.class);
    48→            userDictionary = dictionary.getDictionary(ProductNameDictionary.DICT_USER, SetDictionary.class);
    49→            compoundDictionary = dictionary.getDictionary(ProductNameDictionary.DICT_COMPOUND, CompoundDictionary.class);
    50→            stopDictionary = dictionary.getDictionary(ProductNameDictionary.DICT_STOP, SetDictionary.class);
    51→        }
    52→    }
    53→
    54→    public boolean processRule(List<RuleEntry> queue, boolean fullExtract) {
    55→        logger.trace("queue:{}", queue);
    56→
    57→        if (queue.size() == 1 && queue.get(0).type == null) {
    58→            // not type-split. force split by type
    59→            RuleEntry entry = queue.remove(0);
    60→            Entry.split(entry, queue, 0);
    61→        }
    62→
    63→        if (queue.size() == 1 && queue.get(0).type == SYMBOL) {
    64→            return false;
    65→        }
    66→
    67→        Entry entry = Entry.init(queue);
    68→
    69→        // 1. 규칙분류 시작
    70→        new RuleOne(entry, fullExtract, option, spaceDictionary, stopDictionary, userDictionary, unitDictionary,
    71→                compoundDictionary, extractor).apply(queue);
    72→
    73→        // 2. 변경타입을 생성
    74→        new RuleTwo(entry, fullExtract, option).apply(queue);
    75→
    76→        // 3. 단위명 추출
    77→        new RuleThree(entry, fullExtract, option, unitDictionary, unitSynonymDictionary).apply(queue);
    78→
    79→        // 4. 모델명 추출
    80→        new RuleFour(entry, fullExtract, option, unitDictionary).apply(queue);
    81→
    82→        // 5. 예외규칙적용. 모델명, 단위명을 제외한 모든 텀을 합쳐서 내보낸다
    83→        new RuleFive(entry, fullExtract, option, userDictionary, compoundDictionary).apply(queue);
    84→
    85→        return true;
    86→    }
    87→
    88→    public ProductNameParsingRule clone() {
    89→        ProductNameParsingRule clone = new ProductNameParsingRule();
    90→        clone.extractor = this.extractor;
    91→        clone.option = this.option;
    92→        clone.unitDictionary = this.unitDictionary;
    93→        clone.spaceDictionary = this.spaceDictionary;
    94→        clone.unitSynonymDictionary = this.unitSynonymDictionary;
    95→        clone.synonymDictionary = this.synonymDictionary;
    96→        clone.userDictionary = this.userDictionary;
    97→        clone.compoundDictionary = this.compoundDictionary;
    98→        return clone;
    99→    }
   100→
   101→}
